import {
  buildProjectClause,
  buildProjectMatch,
  labelMatchesProject,
  ProjectMatchContext,
} from './project-match';

/**
 * `KPSF-T-1` — project match rule (`design.md` §8.1). Expected values come from
 * `requirements.md` KPSF-R-2 (positives / negatives / too few words), KPSF-R-9 (safe clause) and
 * KPSF-R-13 (the 182744 label). Fixtures use real CGSpace labels, never regenerated by the code.
 */

const AID_I: ProjectMatchContext = {
  code: 'T-PJ-003942',
  title:
    'IITA Accelerated Innovation Delivery Initiative (AID-I) for Mozambique',
  leadCenter: 'IITA',
};

const FIELD = 'cg.identifier.project';

describe('project-match', () => {
  describe('buildProjectMatch — distinctive words (KPSF-R-2 glossary)', () => {
    it('yields exactly the glossary words for T-PJ-003942', () => {
      expect(buildProjectMatch(AID_I).words).toEqual([
        'accelerated',
        'innovation',
        'delivery',
        'initiative',
        'aid',
        'mozambique',
      ]);
    });

    it('is the same with the lead-center prefix absent from the title', () => {
      const words = buildProjectMatch({
        ...AID_I,
        title:
          'Accelerated Innovation Delivery Initiative (AID-I) for Mozambique',
      }).words;
      expect(words).toEqual(buildProjectMatch(AID_I).words);
    });

    it('drops stopwords (en/fr/es), project, phase, roman numerals and short tokens', () => {
      expect(
        buildProjectMatch({
          title: 'The Project of Phase II des Semillas para el Agua XII ab',
        }).words,
      ).toEqual(['semillas', 'agua']);
    });

    it('drops the code parts (t, pj, its digits) when they appear in the title', () => {
      expect(
        buildProjectMatch({
          code: 'T-PJ-003942',
          title: 'T-PJ-003942 Bean seed systems',
        }).words,
      ).toEqual(['bean', 'seed', 'systems']);
    });

    it('dedupes keeping order and caps at 8', () => {
      const words = buildProjectMatch({
        title:
          'alpha beta alpha gamma delta epsilon zeta theta kappa lambda sigma',
      }).words;
      expect(words).toEqual([
        'alpha',
        'beta',
        'gamma',
        'delta',
        'epsilon',
        'zeta',
        'theta',
        'kappa',
      ]);
    });
  });

  describe('buildProjectMatch — code phrases and usability', () => {
    it('emits the phrase with and without leading zeros', () => {
      expect(buildProjectMatch(AID_I).codePhrases).toEqual([
        'pj 003942',
        'pj 3942',
      ]);
    });

    it('emits a single phrase when the digits have no leading zeros', () => {
      expect(buildProjectMatch({ code: 'T-PJ-123456' }).codePhrases).toEqual([
        'pj 123456',
      ]);
    });

    it('is usable with 2+ words, or with a code, but not with a lone word', () => {
      expect(buildProjectMatch({ title: 'Soil Values' }).usable).toBe(true);
      expect(buildProjectMatch({ code: 'T-PJ-003942' }).usable).toBe(true);
      expect(buildProjectMatch({ title: 'Resilience' }).usable).toBe(false);
      expect(buildProjectMatch({}).usable).toBe(false);
    });
  });

  describe('labelMatchesProject — KPSF-R-2 / KPSF-R-13', () => {
    it.each([
      [
        'prefixed label of 182744 (R-13)',
        'IITA (USA-USAID) - Accelerated Innovation Delivery Initiative (AID-I) for Mozambique',
      ],
      [
        'center-prefixed title',
        'IITA Accelerated Innovation Delivery Initiative (AID-I) for Mozambique',
      ],
      ['code label', 'IITA - T-PJ-003942 AID-I'],
      ['code without leading zeros', 'IITA - PJ 3942 something'],
      [
        'different case and punctuation',
        'accelerated innovation, delivery: initiative; aid - MOZAMBIQUE',
      ],
    ])('matches: %s', (_name, label) => {
      expect(labelMatchesProject(label, AID_I)).toBe(true);
    });

    it.each([
      [
        'sibling initiative missing aid and mozambique',
        'CIMMYT (USA-USAID) - Accelerated Innovation Delivery Initiative (AIDI)',
      ],
      ['different code', 'IITA - T-PJ-003763 something'],
      ['hub label', 'IITA - Western Africa Hub'],
      ['code prefix alone', 'T-PJ - something'],
      ['longer number sharing the prefix', 'IITA - T-PJ-0039421 something'],
      ['empty label', ''],
    ])('does not match: %s', (_name, label) => {
      expect(labelMatchesProject(label, AID_I)).toBe(false);
    });

    it('never matches on a single distinctive word alone', () => {
      const ctx: ProjectMatchContext = { title: 'Resilience' };
      expect(labelMatchesProject('Resilience', ctx)).toBe(false);
      expect(labelMatchesProject('Climate Resilience Program', ctx)).toBe(
        false,
      );
    });

    it('with a 1-word title only the code phrase can match', () => {
      const ctx: ProjectMatchContext = {
        code: 'T-PJ-003942',
        title: 'Resilience',
      };
      expect(labelMatchesProject('Resilience', ctx)).toBe(false);
      expect(labelMatchesProject('PJ-003942', ctx)).toBe(true);
    });

    it('matches whole tokens, not substrings', () => {
      const ctx: ProjectMatchContext = { title: 'Soil Values' };
      expect(labelMatchesProject('Soil Valuesx', ctx)).toBe(false);
      expect(labelMatchesProject('Values of soil', ctx)).toBe(true);
    });
  });

  describe('buildProjectClause — KPSF-R-9', () => {
    it('builds words OR code phrases for the given field', () => {
      expect(buildProjectClause(FIELD, AID_I)).toBe(
        `${FIELD}:(accelerated AND innovation AND delivery AND initiative AND aid AND mozambique) OR ${FIELD}:"pj 003942" OR ${FIELD}:"pj 3942"`,
      );
    });

    it('omits the word group when fewer than 2 words', () => {
      expect(
        buildProjectClause(FIELD, { code: 'T-PJ-003942', title: 'Resilience' }),
      ).toBe(`${FIELD}:"pj 003942" OR ${FIELD}:"pj 3942"`);
    });

    it('omits the code phrases when there is no code', () => {
      expect(buildProjectClause(FIELD, { title: 'Soil Values' })).toBe(
        `${FIELD}:(soil AND values)`,
      );
    });

    it('returns null when not usable', () => {
      expect(buildProjectClause(FIELD, { title: 'Resilience' })).toBeNull();
      expect(buildProjectClause(FIELD, {})).toBeNull();
    });

    it('only sanitized tokens reach the clause for a hostile title', () => {
      const clause = buildProjectClause(FIELD, {
        code: 'T-PJ-003942',
        title: 'Soil " : ( ) * ? \\ AND OR NOT Values',
      });
      expect(clause).toBe(
        `${FIELD}:(soil AND values) OR ${FIELD}:"pj 003942" OR ${FIELD}:"pj 3942"`,
      );
      // Remove the syntax the module emits; what is left must be alphanumeric words/digits only.
      const residue = (clause as string)
        .split(`${FIELD}:`)
        .join('')
        .replace(/[()"]/g, ' ')
        .replace(/\b(AND|OR)\b/g, ' ');
      expect(residue).toMatch(/^[a-z0-9 ]*$/);
    });

    it('never emits operator words from the title as bare tokens', () => {
      const clause = buildProjectClause(FIELD, {
        title: 'Seeds and Soil or Water not Values',
      });
      expect(clause).toBe(`${FIELD}:(seeds AND soil AND water AND values)`);
    });
  });
});
